mapper.select:
select st.id, st.exam_id as examId, st.student_id as studentId, st.dept_id as deptId, d.dept_name as deptName, st.class_info as classInfo, u.nick_name as studentName, u.user_name as userName, s.student_no as studentNo, st.theory_score as theoryScore, st.tech_score as practicalScore, (ifnull(st.total_score, 0) - ifnull(st.theory_score, 0) - ifnull(st.tech_score, 0)) as typingScore, st.total_score as totalScore, st.status, st.start_time as startTime, st.deadline_time as deadlineTime, st.auto_submit as autoSubmit, st.submit_time as submitTime from biz_county_exam_student st left join biz_student s on st.student_id = s.student_id left join sys_user u on s.user_id = u.user_id left join sys_dept d on st.dept_id = d.dept_id where st.exam_id = #{examId}
and ( u.nick_name like concat('%', #{keyword}, '%') or u.user_name like concat('%', #{keyword}, '%') or s.student_no like concat('%', #{keyword}, '%') or d.dept_name like concat('%', #{keyword}, '%') )
order by d.dept_name asc, st.class_info asc, cast(s.student_no as unsigned) asc, s.student_no asc

mapper.update:
update biz_county_exam_student
total_score = #{totalScore}, theory_score = #{theoryScore}, tech_score = #{techScore}, status = #{status}, start_time = #{startTime}, deadline_time = #{deadlineTime}, auto_submit = #{autoSubmit}, submit_time = #{submitTime},
where id = #{id}
